package com.afterfall.narrator;

import com.afterfall.domain.EventId;
import com.afterfall.domain.SurvivorId;
import com.afterfall.events.EventSeverity;

import java.util.List;
import java.util.Objects;

/**
 * Immutable story caption generated by the Narrator.
 *
 * <p>Every caption links directly to its source simulation {@link EventId}s and
 * referenced {@link SurvivorId}s. The Narrator never invents facts not grounded in events.
 */
public record StoryCaption(
        long captionId,
        long tick,
        String text,
        EventSeverity severity,
        List<EventId> sourceEventIds,
        List<SurvivorId> referencedSurvivorIds
) {
    public StoryCaption {
        Objects.requireNonNull(text, "text");
        Objects.requireNonNull(severity, "severity");
        sourceEventIds = List.copyOf(Objects.requireNonNull(sourceEventIds, "sourceEventIds"));
        referencedSurvivorIds = List.copyOf(Objects.requireNonNull(referencedSurvivorIds, "referencedSurvivorIds"));
    }
}
